import json, math

def length(pts, close=False):
    L = 0.0
    n = len(pts)
    for i in range(n - (0 if close else 1)):
        a, b = pts[i], pts[(i + 1) % n]
        L += math.hypot(b[0] - a[0], b[1] - a[1])
    return round(L)

