def seg_dist(q, line):
    best = 1e9
    for a, b in zip(line, line[1:]):
        dx, dz = b[0] - a[0], b[1] - a[1]; t = max(0, min(1, ((q[0] - a[0]) * dx + (q[1] - a[1]) * dz) / (dx * dx + dz * dz or 1)))
        best = min(best, math.hypot(q[0] - a[0] - dx * t, q[1] - a[1] - dz * t))
    return best
