def bb_need(beam, width, deg): return round(beam / math.sin(math.radians(deg)) + width / math.tan(math.radians(deg)), 1)
def s2_flyover_o(s): return S2_LAGOON_O + (S2_SEA_O - S2_LAGOON_O) * (s - 100) / 32
